import json, sys
for f in sys.argv[1:]:
    print("==", f.split("/")[-2])
    for line in open(f):
        try: e = json.loads(line)
        except Exception: continue
        m = e.get("message") or {}
        c = m.get("content")
        if not isinstance(c, list): continue
        for x in c:
            if x.get("type") == "tool_use" and "init" in str(x.get("input", {}).get("command", "")):
                print("CMD", x["input"].get("command", "")[:140].replace("\n", " "), "| bg=", x["input"].get("run_in_background"), "timeout=", x["input"].get("timeout"))
            if x.get("type") == "tool_result" and ("registry" in str(x.get("content", "")) or "init" in str(x.get("content", ""))[:400]):
                print("RES", str(x.get("content"))[:260].replace("\\n", " "))
PYEOF
